 body.innerHTML=`<div class="book-toolbar"><button class="button quiet" data-act="book-back"><span class="reverse">${icon('arrow',15)}</span> 이전</button><strong>${esc(BOOKS[book].name)}</strong></div><div class="book-spread">${list.slice(page*2,page*2+2).map(r=>{
 const n=E.stars(state,r.id),count=state.mastery[r.id]||0,next=r.milestones[n],available=E.canCook(state,r),eventClosed=r.event&&state.events[r.event]!=='active';
 return `<article class="recipe-page ${available?'':'locked'}"><span class="page-kicker">${BOOKS[book].subtitle}</span><h2>${r.name}</h2><div class="food-portrait">${sprite('food',r.sprite)}${!available?`<span class="lock-tag">${eventClosed?'이벤트 기간 한정':`레시피 Lv.${r.required}`}</span>`:''}</div><p class="recipe-description">${r.description}</p><div class="recipe-facts"><span>${icon('clock',15)} ${formatTime(r.duration)}</span><span>${icon('box',15)} 1회 ${r.servings}개 생산</span></div><dl class="recipe-prices"><div><dt>조리 비용</dt><dd>${r.hearts?`${heart()} ${r.hearts}심장`:r.coins?`${coin()} ${r.coins}코인`:'무료'}</dd></div><div><dt>1개당 판매가</dt><dd>${coin()} ${r.price}코인</dd></div></dl><p class="recipe-stock">서빙대 재고 <strong data-food-stock="${r.id}">${num(state.objects.reduce((sum,o)=>sum+(o.foodId===r.id&&furniture(o.type)?.category==='server'?o.stock||0:0),0))}개</strong></p><div class="mastery"><div><span>숙련도 ${count} / ${next||count}</span><b>${'★'.repeat(n)}<i>${'☆'.repeat(3-n)}</i></b></div><div class="mastery-track"><i style="width:${next?Math.min(100,count/next*100):100}%"></i></div><small>${next?`누적 ${count} / ${next}회 · 다음 숙련도까지 ${next-count}회`:'이 요리의 손맛을 완전히 익혔어요!'}</small></div><button class="button ${available?'primary':'disabled'} cook-button" data-act="cook" data-id="${r.id}" ${!available||!stove?'disabled':''}>${available?`${r.hearts?heart():coin()} ${r.hearts||r.coins} · 조리 시작`:`${eventClosed?'지금은 조리할 수 없어요':`레시피 레벨 ${r.required} 필요`}`}</button></article>`;
 }).join('')}</div><div class="book-footer"><button class="icon-button" data-act="book-page" data-n="-1" aria-label="이전 페이지" ${page===0?'disabled':''}><span class="reverse">${icon('arrow',18)}</span></button><span>${page+1} / ${pages} <small>· ${stove?'빈 가마솥에서 조리해요':'빈 가마솥이 없어요. 완성 요리를 먼저 회수하세요.'}</small></span><button class="icon-button" data-act="book-page" data-n="1" aria-label="다음 페이지" ${page>=pages-1?'disabled':''}>${icon('arrow',18)}</button></div>`;
